CREATE OR REPLACE FUNCTION public.create_nutrition_enrollment_atomic(p_program_id uuid, p_coach_id uuid, p_client_id uuid, p_start_date date, p_duration_weeks integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enrollment_id uuid;
  v_day record;
  v_meal record;
  v_food record;
  v_scheduled date;
  v_iso_start int;
  v_assignment_id uuid;
  w int;
  v_basis numeric;
begin
  if p_duration_weeks is null or p_duration_weeks <= 0 then
    raise exception 'Duration must be a positive number of weeks';
  end if;
  if p_duration_weeks > 52 then
    raise exception 'Duration must be 52 weeks or fewer';
  end if;
  if auth.role() <> 'service_role' then
    if not exists (
      select 1 from coaches where id = p_coach_id and user_id = auth.uid()
    ) then
      raise exception 'Not authorized for this coach';
    end if;
  end if;
  if not exists (
    select 1 from nutrition_programs
    where id = p_program_id and coach_id = p_coach_id
  ) then
    raise exception 'Program not found or not owned by this coach';
  end if;
  if not exists (
    select 1 from nutrition_program_days where program_id = p_program_id
  ) then
    raise exception 'Program has no days configured';
  end if;

  insert into client_nutrition_enrollments (program_id, coach_id, client_id, start_date, duration_weeks)
  values (p_program_id, p_coach_id, p_client_id, p_start_date, p_duration_weeks)
  returning id into v_enrollment_id;

  v_iso_start := extract(isodow from p_start_date)::int;

  for w in 1..p_duration_weeks loop
    for v_day in
      select id, day_of_week from nutrition_program_days
      where program_id = p_program_id order by day_of_week
    loop
      if w = 1 and v_day.day_of_week < v_iso_start then
        continue;
      end if;
      v_scheduled := p_start_date + (w - 1) * 7 + (v_day.day_of_week - v_iso_start);

      for v_meal in
        select id, name, order_index from nutrition_program_meals
        where day_id = v_day.id order by order_index
      loop
        insert into nutrition_assignments
          (enrollment_id, coach_id, client_id, scheduled_date, week_number, program_meal_id, meal_name, order_index, status)
        values
          (v_enrollment_id, p_coach_id, p_client_id, v_scheduled, w, v_meal.id, v_meal.name, v_meal.order_index, 'assigned')
        returning id into v_assignment_id;

        for v_food in
          select pf.id as template_food_id, pf.food_id, pf.quantity, pf.order_index,
                 f.name as food_name, f.serving_unit, f.serving_size,
                 f.calories, f.protein_g, f.carbs_g, f.fat_g
          from nutrition_program_foods pf
          join foods f on f.id = pf.food_id
          where pf.meal_id = v_meal.id order by pf.order_index
        loop
          v_basis := nullif(v_food.serving_size, 0);
          if v_basis is null then v_basis := 1; end if;
          insert into nutrition_assignment_foods
            (assignment_id, template_food_id, food_id, food_name, serving_unit, serving_size,
             original_quantity, original_calories, original_protein_g, original_carbs_g, original_fat_g,
             order_index)
          values
            (v_assignment_id, v_food.template_food_id, v_food.food_id, v_food.food_name,
             v_food.serving_unit, v_food.serving_size,
             v_food.quantity,
             round(v_food.calories * v_food.quantity / v_basis),
             round((v_food.protein_g * v_food.quantity / v_basis)::numeric, 1),
             round((v_food.carbs_g * v_food.quantity / v_basis)::numeric, 1),
             round((v_food.fat_g * v_food.quantity / v_basis)::numeric, 1),
             v_food.order_index);
        end loop;
      end loop;
    end loop;
  end loop;

  return v_enrollment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_program_enrollment_atomic(p_program_id uuid, p_coach_id uuid, p_client_id uuid, p_start_date date, p_duration_weeks integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enrollment_id uuid;
  v_day record;
  v_scheduled date;
  v_iso_start int;
  w int;
begin
  -- Ownership (authenticated IDOR fix): same pattern as
  -- upsert_coach_program_atomic above.
  if auth.role() <> 'service_role' then
    if not exists (
      select 1 from coaches
      where id = p_coach_id and user_id = auth.uid()
    ) then
      raise exception 'Not authorized for this coach';
    end if;
  end if;

  if p_duration_weeks is null or p_duration_weeks <= 0 then
    raise exception 'Duration must be a positive number of weeks';
  end if;
  if not exists (
    select 1 from coach_programs
    where id = p_program_id and coach_id = p_coach_id
  ) then
    raise exception 'Program not found or not owned by this coach';
  end if;
  if exists (
    select 1 from coach_program_days where program_id = p_program_id
  ) = false then
    raise exception 'Program has no training days configured';
  end if;

  insert into client_program_enrollments (program_id, coach_id, client_id, start_date, duration_weeks)
  values (p_program_id, p_coach_id, p_client_id, p_start_date, p_duration_weeks)
  returning id into v_enrollment_id;

  v_iso_start := extract(isodow from p_start_date)::int; -- 1 = Monday .. 7 = Sunday

  for w in 1..p_duration_weeks loop
    for v_day in
      select day_of_week, template_id
      from coach_program_days
      where program_id = p_program_id
      order by day_of_week
    loop
      if w = 1 and v_day.day_of_week < v_iso_start then
        continue; -- that weekday already passed before start_date in week 1
      end if;
      v_scheduled := p_start_date + (w - 1) * 7 + (v_day.day_of_week - v_iso_start);
      insert into workout_assignments
        (template_id, coach_id, client_id, scheduled_date, status, enrollment_id, week_number, program_id)
      values
        (v_day.template_id, p_coach_id, p_client_id, v_scheduled, 'assigned', v_enrollment_id, w, null);
    end loop;
  end loop;

  return v_enrollment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_streak_status()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  s public.user_streaks;
  v_logged_today boolean;
begin
  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  select * into s from user_streaks where user_id = v_user_id;

  select exists(
    select 1 from streak_activity_log
    where user_id = v_user_id and activity_date = current_date
  ) into v_logged_today;

  return json_build_object(
    'current_streak', coalesce(s.current_streak, 0),
    'longest_streak', coalesce(s.longest_streak, 0),
    'last_active_date', s.last_active_date,
    'logged_today', v_logged_today,
    'at_risk',
      coalesce(s.current_streak, 0) > 0
      and s.last_active_date = current_date - 1
      and not v_logged_today,
    'freeze_available', coalesce(s.freeze_available, 1)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_notification_read(p_notification_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Ownership (F2 fix): fail closed on unknown ids or cross-user ids.
  if auth.role() <> 'service_role' then
    if p_user_id is null or p_user_id <> auth.uid() then
      raise exception 'Not authorized';
    end if;
    if not exists (
      select 1 from notifications
      where id = p_notification_id and user_id = auth.uid()
    ) then
      raise exception 'Not authorized';
    end if;
  end if;

  UPDATE notifications SET is_read = true WHERE id = p_notification_id AND user_id = p_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_new_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  r uuid;
  sender_name text;
  preview text;
  content text;
BEGIN
  SELECT CASE WHEN NEW.sender_id = c.client_id THEN c.coach_id ELSE c.client_id END INTO r
  FROM conversations c WHERE c.id = NEW.conversation_id;
  IF r IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT coalesce(full_name, name, 'CoreGym') INTO sender_name
  FROM profiles WHERE id = NEW.sender_id;

  content := coalesce(NEW.content, '');
  IF NEW.type = 'voice' THEN
    preview := '🎤 Voice message (' || content || 's)';
  ELSIF NEW.type = 'image' THEN
    preview := '📷 Photo';
  ELSIF NEW.type = 'file' THEN
    preview := '📎 ' || coalesce(CASE WHEN content LIKE '{%' THEN (content::jsonb->>'name') END, 'File');
  ELSE
    preview := substr(content, 1, 60);
  END IF;

  INSERT INTO notifications (user_id, type, title, body, conversation_id)
  VALUES (r, 'message', sender_name, preview, NEW.conversation_id);

  PERFORM net.http_post(
    url := 'https://mkrjvrnysuvtokqkyoll.supabase.co/functions/v1/send-chat-push',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'coregym_cron_secret')
    ),
    body := jsonb_build_object(
      'recipient_id', r,
      'sender_name', sender_name,
      'preview', preview,
      'conversation_id', NEW.conversation_id
    )
  );

  RETURN NEW;
END;
$function$

