CREATE OR REPLACE FUNCTION public.regenerate_remaining_enrollment_assignments(p_enrollment_id uuid, p_coach_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enrollment client_program_enrollments;
  v_day record;
  v_scheduled date;
  w int;
  v_replaced int := 0;
begin
  -- Ownership (authenticated IDOR fix): same pattern as above. Placed
  -- before the enrollment lookup so cross-coach ids fail closed immediately.
  if auth.role() <> 'service_role' then
    if not exists (
      select 1 from coaches
      where id = p_coach_id and user_id = auth.uid()
    ) then
      raise exception 'Not authorized for this coach';
    end if;
  end if;

  select * into v_enrollment
  from client_program_enrollments
  where id = p_enrollment_id and coach_id = p_coach_id;
  if v_enrollment.id is null then
    raise exception 'Enrollment not found or not owned by this coach';
  end if;
  if v_enrollment.status <> 'active' then
    raise exception 'Only active enrollments can be regenerated';
  end if;

  delete from workout_assignments
  where enrollment_id = p_enrollment_id
    and status = 'assigned'
    and scheduled_date > current_date;

  for w in 1..v_enrollment.duration_weeks loop
    for v_day in
      select day_of_week, template_id
      from coach_program_days
      where program_id = v_enrollment.program_id
      order by day_of_week
    loop
      v_scheduled := v_enrollment.start_date + (w - 1) * 7 + (v_day.day_of_week - extract(isodow from v_enrollment.start_date)::int);
      -- regeneration covers only the affected range (today forward); week-1
      -- slots before start_date are automatically excluded by this filter
      if v_scheduled <= current_date then
        continue;
      end if;
      -- a slot whose row survived the delete (completed / started / skipped)
      -- must keep its existing assignment — never create a duplicate
      if exists (
        select 1 from workout_assignments
        where enrollment_id = p_enrollment_id and scheduled_date = v_scheduled
      ) then
        continue;
      end if;
      insert into workout_assignments
        (template_id, coach_id, client_id, scheduled_date, status, enrollment_id, week_number, program_id)
      values
        (v_day.template_id, p_coach_id, v_enrollment.client_id, v_scheduled, 'assigned', p_enrollment_id, w, null);
      v_replaced := v_replaced + 1;
    end loop;
  end loop;

  return v_replaced;
end;
$function$

CREATE OR REPLACE FUNCTION public.regenerate_remaining_nutrition_assignments(p_enrollment_id uuid, p_coach_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enrollment client_nutrition_enrollments;
  v_day record;
  v_meal record;
  v_food record;
  v_scheduled date;
  v_assignment_id uuid;
  v_basis numeric;
  w int;
  v_replaced int := 0;
begin
  select * into v_enrollment
  from client_nutrition_enrollments
  where id = p_enrollment_id and coach_id = p_coach_id;
  if v_enrollment.id is null then
    raise exception 'Enrollment not found or not owned by this coach';
  end if;
  if v_enrollment.status <> 'active' then
    raise exception 'Only active enrollments can be regenerated';
  end if;
  if auth.role() <> 'service_role' then
    if not exists (
      select 1 from coaches where id = p_coach_id and user_id = auth.uid()
    ) then
      raise exception 'Not authorized for this coach';
    end if;
  end if;

  -- Remove only pristine future rows (assigned, future, no client change).
  delete from nutrition_assignments a
  where a.enrollment_id = p_enrollment_id
    and a.status = 'assigned'
    and a.scheduled_date > current_date
    and not exists (
      select 1 from nutrition_assignment_foods f
      where f.assignment_id = a.id and f.change_type is not null
    );

  for w in 1..v_enrollment.duration_weeks loop
    for v_day in
      select id, day_of_week from nutrition_program_days
      where program_id = v_enrollment.program_id order by day_of_week
    loop
      v_scheduled := v_enrollment.start_date + (w - 1) * 7
        + (v_day.day_of_week - extract(isodow from v_enrollment.start_date)::int);
      -- Never generate before the enrollment starts (week-1 weekdays earlier
      -- than the start weekday) and never on/past elapsed dates.
      if v_scheduled < v_enrollment.start_date then
        continue;
      end if;
      if v_scheduled <= current_date then
        continue;
      end if;
      for v_meal in
        select id, name, order_index from nutrition_program_meals
        where day_id = v_day.id order by order_index
      loop
        -- A slot whose row survived the delete (completed / skipped /
        -- changed) keeps its assignment — never duplicate.
        if exists (
          select 1 from nutrition_assignments a
          where a.enrollment_id = p_enrollment_id
            and a.scheduled_date = v_scheduled
            and a.program_meal_id = v_meal.id
        ) then
          continue;
        end if;
        insert into nutrition_assignments
          (enrollment_id, coach_id, client_id, scheduled_date, week_number, program_meal_id, meal_name, order_index, status)
        values
          (p_enrollment_id, p_coach_id, v_enrollment.client_id, v_scheduled, w, v_meal.id, v_meal.name, v_meal.order_index, 'assigned')
        returning id into v_assignment_id;
        for v_food in
          select pf.id as template_food_id, pf.food_id, pf.quantity, pf.order_index,
                 f.name as food_name, f.serving_unit, f.serving_size,
                 f.calories, f.protein_g, f.carbs_g, f.fat_g
          from nutrition_program_foods pf
          join foods f on f.id = pf.food_id
          where pf.meal_id = v_meal.id order by pf.order_index
        loop
          v_basis := nullif(v_food.serving_size, 0);
          if v_basis is null then v_basis := 1; end if;
          insert into nutrition_assignment_foods
            (assignment_id, template_food_id, food_id, food_name, serving_unit, serving_size,
             original_quantity, original_calories, original_protein_g, original_carbs_g, original_fat_g,
             order_index)
          values
            (v_assignment_id, v_food.template_food_id, v_food.food_id, v_food.food_name,
             v_food.serving_unit, v_food.serving_size,
             v_food.quantity,
             round(v_food.calories * v_food.quantity / v_basis),
             round((v_food.protein_g * v_food.quantity / v_basis)::numeric, 1),
             round((v_food.carbs_g * v_food.quantity / v_basis)::numeric, 1),
             round((v_food.fat_g * v_food.quantity / v_basis)::numeric, 1),
             v_food.order_index);
        end loop;
        v_replaced := v_replaced + 1;
      end loop;
    end loop;
  end loop;

  return v_replaced;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_workout_to_summary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_date date;
  v_user uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_date := OLD.session_date;
    v_user := OLD.user_id;
  ELSE
    v_date := NEW.session_date;
    v_user := NEW.user_id;
  END IF;

  INSERT INTO daily_summary (user_id, summary_date, workout_done, workout_duration)
  SELECT
    v_user,
    v_date,
    COUNT(*) > 0,
    COALESCE(SUM(duration_min), 0)
  FROM workout_sessions
  WHERE user_id = v_user AND session_date = v_date
  ON CONFLICT (user_id, summary_date)
  DO UPDATE SET
    workout_done     = EXCLUDED.workout_done,
    workout_duration = EXCLUDED.workout_duration,
    updated_at       = now();

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.unread_count(p_user_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count bigint;
begin
  -- Ownership (F2 fix): direct JWT callers may only read their own total.
  if auth.role() <> 'service_role' then
    if p_user_id is null or p_user_id <> auth.uid() then
      raise exception 'Not authorized';
    end if;
  end if;

  SELECT COALESCE(
    SUM(
      CASE
        WHEN c.client_id = p_user_id THEN c.client_unread
        WHEN c.coach_id  = p_user_id THEN c.coach_unread
        ELSE 0
      END
    ), 0
  )
  INTO v_count
  FROM conversations c
  WHERE c.client_id = p_user_id OR c.coach_id = p_user_id;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_coach_program_atomic(p_program_id uuid, p_coach_id uuid, p_name text, p_description text, p_days jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_program_id uuid;
  v_day jsonb;
begin
  -- Ownership (authenticated IDOR fix): direct JWT callers must own the
  -- coach row (auth.uid() → coaches.user_id → coaches.id). service_role
  -- calls skip this — the API routes verify ownership before calling.
  if auth.role() <> 'service_role' then
    if not exists (
      select 1 from coaches
      where id = p_coach_id and user_id = auth.uid()
    ) then
      raise exception 'Not authorized for this coach';
    end if;
  end if;

  if p_name is null or btrim(p_name) = '' then
    raise exception 'Program name is required';
  end if;
  if p_days is null or jsonb_typeof(p_days) <> 'array'
     or jsonb_array_length(p_days) = 0 then
    raise exception 'At least one weekday must have a template';
  end if;

  -- validate days: ISO 1..7, no duplicates, template must belong to this coach
  if exists (
    select 1
    from jsonb_array_elements(p_days) d
    where (d->>'day_of_week')::smallint not between 1 and 7
  ) then
    raise exception 'day_of_week must be 1 (Monday) .. 7 (Sunday)';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_days) d
    group by (d->>'day_of_week')
    having count(*) > 1
  ) then
    raise exception 'Each weekday can only appear once';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_days) d
    where not exists (
      select 1 from workout_templates t
      where t.id = (d->>'template_id')::uuid and t.coach_id = p_coach_id
    )
  ) then
    raise exception 'Every template must be one of your own workout templates';
  end if;

  if p_program_id is null then
    insert into coach_programs (coach_id, name, description)
    values (p_coach_id, p_name, p_description)
    returning id into v_program_id;
  else
    if not exists (
      select 1 from coach_programs
      where id = p_program_id and coach_id = p_coach_id
    ) then
      raise exception 'Program not found or not owned by this coach';
    end if;
    update coach_programs
    set name = p_name, description = p_description
    where id = p_program_id;
    v_program_id = p_program_id;
    delete from coach_program_days where program_id = v_program_id;
  end if;

  for v_day in select * from jsonb_array_elements(p_days) loop
    insert into coach_program_days (program_id, day_of_week, template_id, order_index)
    values (
      v_program_id,
      (v_day->>'day_of_week')::smallint,
      (v_day->>'template_id')::uuid,
      coalesce(nullif(v_day->>'order_index', '')::int, 0)
    );
  end loop;

  return v_program_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_nutrition_program_atomic(p_program_id uuid, p_coach_id uuid, p_name text, p_description text, p_tree jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_program_id uuid;
  v_day jsonb;
  v_meal jsonb;
  v_food jsonb;
  v_day_id uuid;
  v_meal_id uuid;
  v_meal_idx int;
  v_food_idx int;
begin
  if p_name is null or btrim(p_name) = '' then
    raise exception 'Program name is required';
  end if;
  if char_length(p_name) > 200 then
    raise exception 'Program name must be 200 characters or fewer';
  end if;
  -- Defense in depth: when invoked with a user JWT (not via the dashboard's
  -- service-role API routes), the caller must own the coach row. service_role
  -- calls skip this because the API route already authenticated + verified
  -- ownership before calling.
  if auth.role() <> 'service_role' then
    if not exists (
      select 1 from coaches where id = p_coach_id and user_id = auth.uid()
    ) then
      raise exception 'Not authorized for this coach';
    end if;
  end if;
  if p_tree is null or jsonb_typeof(p_tree) <> 'array'
     or jsonb_array_length(p_tree) = 0 then
    raise exception 'At least one day must have meals';
  end if;
  -- Payload caps: 7 weekdays is structural (unique day_of_week); cap meals
  -- per day and foods per meal so a malformed client cannot fan out rows.
  if exists (
    select 1 from jsonb_array_elements(p_tree) d
    where jsonb_array_length(coalesce(d->'meals', '[]'::jsonb)) > 20
  ) then
    raise exception 'A day can have at most 20 meals';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_tree) d,
      jsonb_array_elements(coalesce(d->'meals', '[]'::jsonb)) m
    where jsonb_array_length(coalesce(m->'foods', '[]'::jsonb)) > 50
  ) then
    raise exception 'A meal can have at most 50 foods';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_tree) d
    where (d->>'day_of_week')::smallint not between 1 and 7
  ) then
    raise exception 'day_of_week must be 1 (Monday) .. 7 (Sunday)';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_tree) d
    group by (d->>'day_of_week') having count(*) > 1
  ) then
    raise exception 'Each weekday can only appear once';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_tree) d,
      jsonb_array_elements(coalesce(d->'meals', '[]'::jsonb)) m,
      jsonb_array_elements(coalesce(m->'foods', '[]'::jsonb)) f
    where not exists (
      select 1 from foods where id = (f->>'food_id')::uuid
    )
  ) then
    raise exception 'Every food must reference the food library';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_tree) d,
      jsonb_array_elements(coalesce(d->'meals', '[]'::jsonb)) m,
      jsonb_array_elements(coalesce(m->'foods', '[]'::jsonb)) f
    where coalesce((f->>'quantity')::numeric, 0) <= 0
  ) then
    raise exception 'Every food quantity must be greater than 0';
  end if;

  if p_program_id is null then
    insert into nutrition_programs (coach_id, name, description)
    values (p_coach_id, p_name, p_description)
    returning id into v_program_id;
  else
    if not exists (
      select 1 from nutrition_programs
      where id = p_program_id and coach_id = p_coach_id
    ) then
      raise exception 'Program not found or not owned by this coach';
    end if;
    update nutrition_programs
    set name = p_name, description = p_description
    where id = p_program_id;
    v_program_id = p_program_id;
    delete from nutrition_program_days where program_id = v_program_id;
  end if;

  for v_day in select * from jsonb_array_elements(p_tree) loop
    insert into nutrition_program_days (program_id, day_of_week, notes)
    values (
      v_program_id,
      (v_day->>'day_of_week')::smallint,
      nullif(v_day->>'notes', '')
    )
    returning id into v_day_id;

    v_meal_idx := 0;
    for v_meal in select * from jsonb_array_elements(coalesce(v_day->'meals', '[]'::jsonb)) loop
      if v_meal->>'name' is null or btrim(v_meal->>'name') = '' then
        raise exception 'Every meal must have a name';
      end if;
      insert into nutrition_program_meals (day_id, name, order_index)
      values (v_day_id, btrim(v_meal->>'name'), v_meal_idx)
      returning id into v_meal_id;

      v_food_idx := 0;
      for v_food in select * from jsonb_array_elements(coalesce(v_meal->'foods', '[]'::jsonb)) loop
        insert into nutrition_program_foods (meal_id, food_id, quantity, order_index)
        values (
          v_meal_id,
          (v_food->>'food_id')::uuid,
          (v_food->>'quantity')::numeric,
          v_food_idx
        );
        v_food_idx := v_food_idx + 1;
      end loop;
      v_meal_idx := v_meal_idx + 1;
    end loop;
  end loop;

  return v_program_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.wt_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
